source='''def transform(grid):
    h, w = len(grid), len(grid[0])
    orientations = [
        (lambda r, c: r),       # horizontal stripes
        (lambda r, c: c),       # vertical stripes
        (lambda r, c: r - c),   # down-right stripes
        (lambda r, c: r + c),   # down-left stripes
    ]
    best = None
    for key_fn in orientations:
        groups = {}
        for r in range(h):
            for c in range(w):
                groups.setdefault(key_fn(r, c), []).append((r, c))
        stripes = {}
        for k, cells in groups.items():
            vals = [grid[r][c] for r, c in cells]
            if vals and vals[0] != 0 and all(v == vals[0] for v in vals):
                stripes[k] = vals[0]
        score = sum(len(groups[k]) for k in stripes)
        if best is None or score > best[0]:
            best = (score, key_fn, groups, stripes)
    _, key_fn, groups, stripes = best
    if not stripes:
        return [row[:] for row in grid]

    # Find the shortest repeating stripe period consistent with every marked line.
    max_period = max(1, 2 * max(h, w))
    period = 1
    for p in range(1, max_period + 1):
        residues = {}
        valid = True
        for k, color in stripes.items():
            residue = k % p
            if residue in residues and residues[residue] != color:
                valid = False
                break
            residues[residue] = color
        if valid:
            period = p
            break

    colors = {}
    for k, color in stripes.items():
        colors[k % period] = color
    out = [[0] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            residue = key_fn(r, c) % period
            if residue in colors:
                out[r][c] = colors[residue]
    return out
'''
